CREATE OR REPLACE FUNCTION public.register_unit_contract(_unit_id uuid,_booking_id uuid,_tenant_account_id uuid,_number text,_starts_on date,_ends_on date,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE id uuid;BEGIN PERFORM public._assert_admin_writer();PERFORM public._assert_reason(_reason);IF nullif(btrim(_number),'') IS NULL OR _starts_on IS NULL OR _ends_on IS NULL OR _ends_on<_starts_on THEN RAISE EXCEPTION 'رقم العقد وتواريخه الصحيحة مطلوبة'; END IF; PERFORM 1 FROM public.units WHERE units.id=_unit_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'الوحدة غير موجودة'; END IF;IF _booking_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.booking_units WHERE booking_id=_booking_id AND unit_id=_unit_id AND archived_at IS NULL) THEN RAISE EXCEPTION 'الحجز لا يخص الوحدة'; END IF; IF _booking_id IS NULL AND (_tenant_account_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_account_units WHERE tenant_account_id=_tenant_account_id AND unit_id=_unit_id)) THEN RAISE EXCEPTION 'حساب المستأجر المرتبط مطلوب للعقد التاريخي'; END IF;INSERT INTO public.unit_contracts(unit_id,booking_id,tenant_account_id,contract_number,starts_on,ends_on,created_by,status_reason) VALUES(_unit_id,_booking_id,_tenant_account_id,btrim(_number),_starts_on,_ends_on,auth.uid(),_reason) RETURNING unit_contracts.id INTO id;PERFORM public._safety_audit('REGISTER_CONTRACT','unit_contracts',id::text,NULL,(SELECT to_jsonb(c) FROM public.unit_contracts c WHERE c.id=id),_reason);RETURN id;END $$;
CREATE OR REPLACE FUNCTION public.set_unit_contract_state(_contract_id uuid,_status text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.unit_contracts;BEGIN PERFORM public._assert_admin_writer();PERFORM public._assert_reason(_reason);SELECT * INTO c FROM public.unit_contracts WHERE id=_contract_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'العقد غير موجود'; END IF;IF NOT((c.status='draft' AND _status='active') OR (c.status='active' AND _status IN ('ended','terminated'))) THEN RAISE EXCEPTION 'انتقال حالة العقد غير مسموح'; END IF;IF _status='active' AND (c.starts_on IS NULL OR c.ends_on IS NULL OR c.starts_on>current_date OR c.ends_on<current_date) THEN RAISE EXCEPTION 'العقد خارج مدة السريان'; END IF;IF _status='ended' AND c.ends_on>current_date THEN RAISE EXCEPTION 'العقد لم تنته مدته؛ استخدم الإنهاء بسبب'; END IF;UPDATE public.unit_contracts SET status=_status,status_reason=_reason,updated_at=now() WHERE id=c.id;IF _status IN ('ended','terminated') THEN UPDATE public.tenants SET archived_at=now(),archived_by=auth.uid(),archive_reason=_reason WHERE unit_id=c.unit_id AND archived_at IS NULL;IF c.booking_id IS NOT NULL THEN UPDATE public.bookings SET status='cancelled',archived_at=now(),archived_by=auth.uid(),archive_reason=_reason WHERE id=c.booking_id; END IF;PERFORM public.set_unit_status(c.unit_id,'available',_reason,'contract',c.id);END IF;PERFORM public._safety_audit('CONTRACT_STATE','unit_contracts',c.id::text,to_jsonb(c),(SELECT to_jsonb(x) FROM public.unit_contracts x WHERE id=c.id),_reason);END $$;
CREATE OR REPLACE FUNCTION public.verify_unit_first_payment(_contract_id uuid,_receipt_type text,_receipt_id uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.unit_contracts;result uuid;BEGIN PERFORM public._assert_admin_writer();PERFORM public._assert_reason(_reason);IF auth.uid() IS NULL THEN RAISE EXCEPTION 'التحقق يتطلب منفذًا مسجلًا'; END IF;SELECT * INTO c FROM public.unit_contracts WHERE id=_contract_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'العقد غير موجود'; END IF;IF _receipt_type='invoice' THEN IF NOT EXISTS(SELECT 1 FROM public.invoices i WHERE i.id=_receipt_id AND i.archived_at IS NULL AND i.reverses_id IS NULL AND i.paid_amount>0 AND (i.unit_id=c.unit_id OR (c.booking_id IS NOT NULL AND i.booking_id=c.booking_id) OR (c.tenant_account_id IS NOT NULL AND i.tenant_account_id=c.tenant_account_id)) AND NOT EXISTS(SELECT 1 FROM public.invoices r WHERE r.reverses_id=i.id)) THEN RAISE EXCEPTION 'إيصال غير صالح أو لا يخص العقد أو تم عكسه'; END IF;ELSIF _receipt_type='collection' THEN IF NOT EXISTS(SELECT 1 FROM public.unit_collections x WHERE x.id=_receipt_id AND x.unit_id=c.unit_id AND (c.tenant_account_id IS NULL OR x.tenant_account_id=c.tenant_account_id) AND NOT x.is_archived AND x.reverses_id IS NULL AND x.amount>0 AND NOT EXISTS(SELECT 1 FROM public.unit_collections r WHERE r.reverses_id=x.id)) THEN RAISE EXCEPTION 'إيصال تحصيل غير صالح أو معكوس'; END IF;ELSE RAISE EXCEPTION 'نوع الإيصال غير صالح';END IF;INSERT INTO public.unit_first_payment_verifications(contract_id,receipt_type,receipt_id,verified_by,reason) VALUES(c.id,_receipt_type,_receipt_id,auth.uid(),_reason) RETURNING id INTO result;PERFORM public._safety_audit('VERIFY_FIRST_PAYMENT','unit_first_payment_verifications',result::text,NULL,(SELECT to_jsonb(v) FROM public.unit_first_payment_verifications v WHERE id=result),_reason);RETURN result;END $$;
CREATE OR REPLACE FUNCTION public.initialize_unit_leasing_status(_unit_id uuid,_status public.unit_leasing_status,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.units;BEGIN PERFORM public._assert_admin_writer();PERFORM public._assert_reason(_reason);SELECT * INTO u FROM public.units WHERE id=_unit_id FOR UPDATE;IF NOT FOUND OR u.leasing_status IS NOT NULL THEN RAISE EXCEPTION 'التهيئة للوحدات الجديدة أو قيد المراجعة فقط'; END IF;IF _status NOT IN ('available','blocked') THEN RAISE EXCEPTION 'التسوية تتيح الإيقاف أو الإتاحة بعد التحقق فقط'; END IF;IF _status='available' AND (EXISTS(SELECT 1 FROM public.tenants WHERE unit_id=u.id AND archived_at IS NULL) OR EXISTS(SELECT 1 FROM public.booking_units bu JOIN public.bookings b ON b.id=bu.booking_id WHERE bu.unit_id=u.id AND bu.archived_at IS NULL AND b.archived_at IS NULL AND b.status IN ('pending','confirmed')) OR EXISTS(SELECT 1 FROM public.unit_contracts WHERE unit_id=u.id AND status='active')) THEN RAISE EXCEPTION 'الوحدة عليها إشغال؛ لا يمكن إتاحتها'; END IF;INSERT INTO public.unit_status_write_capabilities VALUES(txid_current(),u.id) ON CONFLICT DO NOTHING;UPDATE public.units SET leasing_status=_status,leasing_status_initialized=true WHERE id=u.id;DELETE FROM public.unit_status_write_capabilities WHERE transaction_id=txid_current() AND unit_id=u.id;UPDATE public.unit_status_backfill_review SET resolved_at=now(),resolved_by=auth.uid(),proposed_status=_status,reason=_reason WHERE unit_id=u.id;INSERT INTO public.unit_status_history(unit_id,to_status,actor,actor_role,reason,ref_type) VALUES(u.id,_status,auth.uid(),'admin',_reason,'review_resolution');PERFORM public._safety_audit('UNIT_STATUS_REVIEW','units',u.id::text,to_jsonb(u),(SELECT to_jsonb(x) FROM public.units x WHERE id=u.id),_reason);END $$;
CREATE OR REPLACE FUNCTION public.leasing_manager_bookings(_limit integer DEFAULT 25,_offset integer DEFAULT 0,_search text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rows jsonb;total bigint;BEGIN IF NOT public.has_role(auth.uid(),'leasing_manager') THEN RAISE EXCEPTION 'غير مصرح'; END IF;SELECT count(*) INTO total FROM public.bookings b WHERE b.status='pending' AND b.archived_at IS NULL AND (coalesce(_search,'')='' OR b.offer_number ILIKE '%'||_search||'%');SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO rows FROM (SELECT id,offer_number,expires_at,hold_extensions FROM public.bookings b WHERE b.status='pending' AND b.archived_at IS NULL AND (coalesce(_search,'')='' OR b.offer_number ILIKE '%'||_search||'%') ORDER BY expires_at LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0))x;RETURN jsonb_build_object('rows',rows,'total',total);END $$;
DO $$ DECLARE f record;BEGIN FOR f IN SELECT oid::regprocedure sig FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('register_unit_contract','set_unit_contract_state','verify_unit_first_payment','initialize_unit_leasing_status','leasing_manager_bookings') LOOP EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC,anon',f.sig);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',f.sig);END LOOP;END $$;
CREATE OR REPLACE FUNCTION public.unit_leasing_immutable_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'سجل الحالات والتحقق غير قابل للتعديل أو الحذف'; END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['unit_status_history','unit_first_payment_verifications'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname=t||'_immutable') THEN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.unit_leasing_immutable_history()',t||'_immutable',t);END IF;END LOOP;IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='unit_status_only_writer' AND tgrelid='public.units'::regclass) THEN CREATE TRIGGER unit_status_only_writer BEFORE INSERT OR UPDATE ON public.units FOR EACH ROW EXECUTE FUNCTION public.unit_status_write_guard();END IF;END $$;
REVOKE UPDATE ON public.units FROM PUBLIC,authenticated,anon;
REVOKE UPDATE(status,leasing_status,leasing_status_initialized,status_before_maintenance) ON public.units FROM PUBLIC,authenticated,anon;
DO $$ DECLARE cols text;BEGIN SELECT string_agg(quote_ident(column_name),',') INTO cols FROM information_schema.columns WHERE table_schema='public' AND table_name='units' AND column_name NOT IN ('status','leasing_status','leasing_status_initialized','status_before_maintenance');EXECUTE 'GRANT UPDATE ('||cols||') ON public.units TO authenticated';END $$;
COMMENT ON COLUMN public.units.status IS 'DEPRECATED: frozen historical value, use leasing_status';
COMMENT ON COLUMN public.units.status_before_maintenance IS 'DEPRECATED: frozen historical value, no restoration writes';
SELECT has_column_privilege('authenticated','public.units','leasing_status','UPDATE') AS must_be_false;
SELECT count(*) FROM public.unit_status_backfill_review WHERE resolved_at IS NULL;